#include <genesis.h>
#include "retro_state_machine.h"

/* Generated by Godot Retro Engine from the Inputs editor. */
int main(bool hard)
{
    u16 previous = 0;
    VDP_setScreenWidth320();
    VDP_drawText("RETRO STATE MACHINE", 4, 2);
    retro_sm_init();
    while (TRUE)
    {
        u16 joy = JOY_readJoypad(JOY_1);
        u16 pressed = joy & (u16)(~previous);
        previous = joy;
        retro_sm_update(joy, pressed);
        retro_sm_tick();
        SYS_doVBlankProcess();
    }
    return 0;
}
